import { DurableObject } from "cloudflare:workers";

/* 이 파일은 dev/build.py로 만들어요. 고칠 땐 dev 폴더를 고친 뒤 다시 묶기 */
const INDEX_HTML = "<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#FFF8EE\">\n<title>꼬리별</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Jua&family=Gowun+Dodum&display=swap\">\n<style>\n/* 레이아웃: 위엔 작은 머리띠, 가운데 탭 화면, 아래 탭 3개. 크림 바탕 + 갈색 손그림 테두리 */\n:root {\n  --bg: #FFF8EE; --card: #FFFFFF; --ink: #4A3428; --soft: #8C7466; --line: #EADCCB;\n  --pink: #F2A0B3; --pink-deep: #E07C95; --mint: #CBEBDD; --sky: #DCEBFA; --butter: #FFE7A6; --gold: #F2BE4B;\n  --display: \"Jua\", \"Apple SD Gothic Neo\", \"Malgun Gothic\", sans-serif;\n  --body: \"Gowun Dodum\", \"Apple SD Gothic Neo\", \"Malgun Gothic\", sans-serif;\n  --r: 20px; --stroke: 2.5px solid var(--ink);\n  color-scheme: light;\n}\n* { box-sizing: border-box; }\nhtml, body { margin: 0; height: 100%; }\nbody { background: var(--bg); color: var(--ink); font: 16px/1.5 var(--body); -webkit-tap-highlight-color: transparent; }\nbutton { font: inherit; color: inherit; cursor: pointer; }\nbutton:focus-visible, input:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }\nimg { max-width: 100%; }\n[hidden] { display: none !important; }\nh1, h2, h3 { font-family: var(--display); font-weight: 400; margin: 0; text-wrap: balance; }\n\n.hdr { position: sticky; top: 0; z-index: 5; background: var(--bg); padding: calc(env(safe-area-inset-top, 0px) + 10px) max(16px, env(safe-area-inset-right, 0px)) 8px max(16px, env(safe-area-inset-left, 0px)); display: flex; align-items: center; justify-content: space-between; }\n.hdr h1 { font-size: 26px; letter-spacing: .02em; }\n.hdr h1 span { color: var(--pink-deep); }\n.who { font-size: 14px; color: var(--soft); }\nmain { max-width: 520px; margin: 0 auto; padding: 4px max(16px, env(safe-area-inset-right, 0px)) calc(96px + env(safe-area-inset-bottom, 0px)) max(16px, env(safe-area-inset-left, 0px)); display: flex; flex-direction: column; gap: 16px; }\n.view { display: flex; flex-direction: column; gap: 16px; }\n\n.tabs { position: fixed; left: 0; right: 0; bottom: 0; z-index: 6; background: var(--card); border-top: var(--stroke); display: grid; grid-template-columns: repeat(3, 1fr); padding: 6px max(8px, env(safe-area-inset-right, 0px)) calc(6px + env(safe-area-inset-bottom, 0px)) max(8px, env(safe-area-inset-left, 0px)); }\n.tabs button { border: 0; background: none; padding: 6px 4px; border-radius: 14px; font-family: var(--display); font-size: 16px; color: var(--soft); display: flex; flex-direction: column; align-items: center; gap: 2px; position: relative; }\n.tabs button svg { width: 26px; height: 26px; }\n.tabs button[aria-selected=\"true\"] { color: var(--ink); background: var(--butter); }\n.tabs .dot { position: absolute; top: 4px; right: calc(50% - 22px); width: 10px; height: 10px; border-radius: 50%; background: var(--pink-deep); border: 2px solid var(--card); }\n\n.card { background: var(--card); border: var(--stroke); border-radius: var(--r); padding: 16px; display: flex; flex-direction: column; gap: 12px; }\n.card h2 { font-size: 21px; display: flex; align-items: center; gap: 8px; }\n.note { margin: 0; color: var(--soft); font-size: 14px; }\n.btn { border: var(--stroke); border-radius: 999px; padding: 12px 18px; background: var(--card); font-family: var(--display); font-size: 18px; box-shadow: 0 3px 0 var(--ink); transition: transform .08s; }\n.btn:active { transform: translateY(2px); box-shadow: 0 1px 0 var(--ink); }\n.btn.main { background: var(--pink); }\n.btn.big { width: 100%; font-size: 20px; padding: 14px 18px; }\n.btn:disabled { opacity: .5; box-shadow: none; transform: none; cursor: default; }\n.btn.urgent { background: var(--pink-deep); color: #FFFFFF; animation: pulse 1s ease-in-out infinite; }\n@keyframes pulse { 50% { transform: scale(1.03); } }\n.link { border: 0; background: none; color: var(--soft); text-decoration: underline; font-size: 14px; padding: 4px; align-self: center; }\n.err { color: #C2415A; font-size: 14px; margin: 0; }\n\nlabel.f { display: flex; flex-direction: column; gap: 4px; font-size: 14px; color: var(--soft); }\ninput[type=text] { font: 16px var(--body); color: var(--ink); padding: 12px 14px; border: var(--stroke); border-radius: 14px; background: var(--bg); width: 100%; }\n.chips { display: flex; gap: 8px; flex-wrap: wrap; }\n.chip { border: var(--stroke); border-radius: 999px; padding: 8px 16px; background: var(--card); font-family: var(--display); font-size: 16px; }\n.chip[aria-pressed=\"true\"] { background: var(--mint); }\n\n/* 입장 */\n.gate { position: fixed; inset: 0; z-index: 20; background: var(--bg); display: flex; align-items: center; justify-content: center; padding: 24px max(16px, env(safe-area-inset-right, 0px)) 24px max(16px, env(safe-area-inset-left, 0px)); overflow-y: auto; }\n.gate .card { width: min(380px, 100%); align-items: stretch; text-align: center; }\n.gate img { width: 160px; height: 160px; object-fit: cover; border-radius: 50%; border: var(--stroke); align-self: center; animation: bob 2.6s ease-in-out infinite; }\n.gate h1 { font-size: 34px; }\n.gate h1 span { color: var(--pink-deep); }\n\n/* 사진 → 캐릭터 */\n.drop { position: relative; border: 2.5px dashed var(--soft); border-radius: var(--r); min-height: 150px; display: flex; align-items: center; justify-content: center; text-align: center; color: var(--soft); font-family: var(--display); overflow: hidden; background: var(--bg); }\n.drop input { position: absolute; inset: 0; opacity: 0; width: 100%; height: 100%; cursor: pointer; }\n.drop img { width: 100%; max-height: 260px; object-fit: cover; display: block; }\n.morph { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 8px; }\n.morph .pic { aspect-ratio: 1; border: var(--stroke); border-radius: 18px; overflow: hidden; background: var(--bg); display: flex; align-items: center; justify-content: center; }\n.morph .pic img { width: 100%; height: 100%; object-fit: cover; }\n.morph .arrow { font-family: var(--display); font-size: 26px; color: var(--pink-deep); }\n.loading { font-family: var(--display); color: var(--soft); text-align: center; font-size: 15px; padding: 8px; }\n.loading i { display: block; width: 46px; height: 46px; margin: 0 auto 6px; border-radius: 50%; border: 4px solid var(--line); border-top-color: var(--pink-deep); animation: spin 1s linear infinite; }\n@keyframes spin { to { transform: rotate(360deg); } }\n\n/* 우리 방 */\n.room { position: relative; aspect-ratio: 1 / 1; max-width: 100%; border: var(--stroke); border-radius: var(--r); overflow: hidden; background: linear-gradient(#E7DDF8 0%, #F6E7EE 58%, #F3DDC0 58%, #EED1AE 100%); touch-action: manipulation; }\n.room .it { position: absolute; width: 30%; }\n.room .it svg { width: 100%; height: auto; display: block; }\n.room .lamp { left: 4%; top: 0; width: 22%; }\n.room .cloud { right: 4%; top: 8%; }\n.room .hammock { left: 3%; bottom: 8%; }\n.room .slide { right: 3%; bottom: 8%; }\n.room .pet { position: absolute; left: 50%; bottom: 9%; width: 54%; transform: translateX(-50%); cursor: pointer; }\n.room .pet .bob { animation: bob 2.4s ease-in-out infinite; transform-origin: 50% 100%; }\n.room .pet img { width: 100%; display: block; border-radius: 50%; mix-blend-mode: multiply; }\n.room .bubble { position: absolute; left: 50%; top: 10%; transform: translateX(-50%); background: var(--card); border: var(--stroke); border-radius: 16px; padding: 6px 14px; font-family: var(--display); white-space: nowrap; opacity: 0; transition: opacity .25s; pointer-events: none; }\n.room .bubble.on { opacity: 1; }\n.heart { position: absolute; font-size: 22px; color: var(--pink-deep); pointer-events: none; animation: rise 1.1s ease-out forwards; }\n@keyframes rise { to { transform: translateY(-80px); opacity: 0; } }\n@keyframes bob { 0%,100% { transform: translateY(0) scale(1,1); } 50% { transform: translateY(-6px) scale(1.02,.98); } }\n.petName { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }\n.petName h2 { font-size: 24px; }\n.brag { background: var(--butter); border-radius: 14px; padding: 8px 12px; font-size: 15px; margin: 0; }\n\n/* 갓챠 */\n.roundBar { display: flex; justify-content: space-between; align-items: center; gap: 8px; font-family: var(--display); font-size: 16px; }\n.roundBar .left b { color: var(--pink-deep); font-weight: 400; font-size: 22px; font-variant-numeric: tabular-nums; }\n.roundBar .clock { font-variant-numeric: tabular-nums; color: var(--soft); }\n.machine { display: flex; justify-content: center; }\n.machine svg { width: min(230px, 70%); height: auto; }\n.machine.shake svg { animation: shake .12s linear 8; }\n@keyframes shake { 25% { transform: rotate(-3deg); } 75% { transform: rotate(3deg); } }\n.lineWrap { overflow-x: auto; margin: 0 -16px; padding: 4px 16px 8px; scrollbar-width: none; }\n.line { display: flex; gap: 10px; min-width: min-content; }\n.qp { flex: none; width: 66px; display: flex; flex-direction: column; align-items: center; gap: 2px; font-size: 12px; color: var(--soft); text-align: center; }\n.qp .av { width: 58px; height: 58px; border-radius: 50%; border: var(--stroke); background: var(--bg); overflow: hidden; position: relative; }\n.qp .av img, .qp .av svg { width: 100%; height: 100%; object-fit: cover; display: block; }\n.qp .no { font-family: var(--display); font-size: 14px; color: var(--ink); }\n.qp .nm { max-width: 66px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.qp.me .av { border-color: var(--pink-deep); box-shadow: 0 0 0 3px var(--pink); }\n.qp.me .nm { color: var(--pink-deep); font-family: var(--display); }\n.qp.turn .av { animation: bob .8s ease-in-out infinite; }\n.lineEmpty { color: var(--soft); font-size: 14px; padding: 12px 0; }\n.myLine { text-align: center; font-family: var(--display); font-size: 19px; margin: 0; min-height: 1.5em; }\n.myLine small { display: block; font-family: var(--body); font-size: 14px; color: var(--soft); }\n\n.rank { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }\n.rank li { display: grid; grid-template-columns: 30px 46px 1fr auto; align-items: center; gap: 10px; border: var(--stroke); border-radius: 16px; padding: 6px 12px; background: var(--card); }\n.rank li:nth-child(1) { background: #FFF1C2; }\n.rank li:nth-child(2) { background: #E8F1FB; }\n.rank li:nth-child(3) { background: #FBE6D8; }\n.rank li.mine { box-shadow: 0 0 0 3px var(--pink); }\n.rank .medal { font-family: var(--display); font-size: 18px; text-align: center; }\n.rank .av { width: 46px; height: 46px; border-radius: 50%; overflow: hidden; border: 2px solid var(--ink); background: var(--bg); }\n.rank .av img, .rank .av svg { width: 100%; height: 100%; object-fit: cover; display: block; }\n.rank .nm { min-width: 0; font-family: var(--display); font-size: 16px; line-height: 1.25; }\n.rank .nm small { display: block; font-family: var(--body); font-size: 12px; color: var(--soft); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.rank .ct { font-family: var(--display); color: var(--pink-deep); font-variant-numeric: tabular-nums; white-space: nowrap; }\n.rank .empty { display: block; border: 0; background: none; padding: 0; color: var(--soft); font-size: 14px; }\n\n/* 굿즈 */\n.grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }\n.good { position: relative; display: flex; flex-direction: column; align-items: center; gap: 4px; font-size: 13px; text-align: center; color: var(--soft); min-width: 0; }\n.good .frame { width: 100%; aspect-ratio: 1; position: relative; display: flex; align-items: center; justify-content: center; }\n.good .frame .face { width: 78%; height: 78%; border-radius: 50%; overflow: hidden; position: relative; z-index: 1; }\n.good .frame .face img, .good .frame .face svg { width: 100%; height: 100%; object-fit: cover; display: block; }\n.good .cnt { position: absolute; top: 2px; right: 2px; z-index: 2; background: var(--ink); color: #FFFFFF; font-family: var(--display); font-size: 12px; border-radius: 999px; padding: 0 7px; }\n.good b { font-family: var(--display); font-weight: 400; color: var(--ink); font-size: 14px; line-height: 1.2; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.g-sticker .frame .face { border: 6px solid #FFFFFF; box-shadow: 0 0 0 2.5px var(--ink); transform: rotate(-4deg); }\n.g-keyring .frame { padding-top: 14%; }\n.g-keyring .frame .face { border: var(--stroke); width: 70%; height: 70%; }\n.g-keyring .ring { position: absolute; top: 2%; left: 50%; transform: translateX(-50%); width: 22%; aspect-ratio: 1; border: 3px solid #A9A4AE; border-radius: 50%; }\n.g-plush .frame { background: radial-gradient(circle, #FBD9E2 0 62%, transparent 63%); }\n.g-plush .frame .face { border: 3px dashed var(--pink-deep); }\n.g-figure .frame::after { content: \"\"; position: absolute; bottom: 4%; left: 14%; right: 14%; height: 16%; background: var(--gold); border: var(--stroke); border-radius: 50%; }\n.g-figure .frame .face { border: 3px solid var(--gold); margin-bottom: 12%; filter: saturate(1.1); }\n.g-figure .star { position: absolute; top: 2%; right: 8%; color: var(--gold); font-size: 20px; z-index: 2; }\n.locked { opacity: .45; filter: grayscale(1); }\n.items { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }\n.item { border: var(--stroke); border-radius: 16px; padding: 6px 4px; background: var(--bg); text-align: center; font-size: 12px; display: flex; flex-direction: column; align-items: center; gap: 2px; position: relative; min-width: 0; }\n.item svg { width: 100%; height: auto; }\n.item b { font-family: var(--display); font-weight: 400; font-size: 13px; }\n.item.rare { background: #FFF1C2; }\n\n/* 결과 */\n.modal { position: fixed; inset: 0; z-index: 30; background: rgba(74,52,40,.55); display: flex; align-items: center; justify-content: center; padding: 24px; }\n.modal .card { width: min(340px, 100%); align-items: center; text-align: center; }\n.capsule { width: 150px; height: 150px; position: relative; }\n.capsule .top, .capsule .bot { position: absolute; left: 0; width: 150px; height: 75px; border: 3px solid var(--ink); }\n.capsule .top { top: 0; border-radius: 75px 75px 0 0; background: var(--pink); transition: transform .5s, opacity .5s; }\n.capsule .bot { bottom: 0; border-radius: 0 0 75px 75px; background: #FFFFFF; transition: transform .5s, opacity .5s; }\n.capsule.shake { animation: shake .14s linear 7; }\n.capsule.open .top { transform: translateY(-90px) rotate(-25deg); opacity: 0; }\n.capsule.open .bot { transform: translateY(90px); opacity: 0; }\n.reveal { animation: pop .6s cubic-bezier(.3,1.6,.5,1); width: 170px; }\n@keyframes pop { from { transform: scale(.2); opacity: 0; } }\n.badge { display: inline-block; border: var(--stroke); border-radius: 999px; padding: 2px 12px; font-family: var(--display); font-size: 14px; background: var(--mint); }\n.badge.rare { background: var(--gold); }\n.toast { position: fixed; left: 50%; bottom: calc(92px + env(safe-area-inset-bottom, 0px)); transform: translateX(-50%); z-index: 25; background: var(--ink); color: #FFFFFF; border-radius: 999px; padding: 10px 18px; font-size: 15px; max-width: calc(100% - 32px); text-align: center; }\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; } }\n</style>\n</head>\n<body>\n\n<header class=\"hdr\"><h1>꼬리<span>별</span></h1><span class=\"who\" id=\"who\"></span></header>\n\n<main>\n  <!-- 우리 아이 -->\n  <section class=\"view\" id=\"vPet\" aria-label=\"우리 아이\">\n    <div class=\"card\" id=\"maker\" hidden>\n      <h2>내 사진으로 만들기</h2>\n      <p class=\"note\">우리 애 사진 한 장이면 꼬리별 그림체로 그려 줘요. 얼굴이 잘 보이는 사진이 좋아요</p>\n      <div class=\"drop\" id=\"drop\"><span id=\"dropText\">사진 고르기</span><input type=\"file\" id=\"photo\" accept=\"image/*\" aria-label=\"사진 고르기\"></div>\n      <div class=\"chips\" role=\"group\" aria-label=\"종류\">\n        <button type=\"button\" class=\"chip\" data-kind=\"hamster\" aria-pressed=\"true\">햄찌</button>\n        <button type=\"button\" class=\"chip\" data-kind=\"dog\" aria-pressed=\"false\">강아지</button>\n        <button type=\"button\" class=\"chip\" data-kind=\"cat\" aria-pressed=\"false\">고양이</button>\n      </div>\n      <label class=\"f\">이름<input type=\"text\" id=\"petName\" maxlength=\"12\" placeholder=\"예: 자장이\" autocomplete=\"off\"></label>\n      <p class=\"err\" id=\"makeErr\" hidden></p>\n      <button type=\"button\" class=\"btn main big\" id=\"btnDraw\">꼬리별 그림체로 그리기</button>\n      <p class=\"note\" id=\"drawLeft\"></p>\n      <div id=\"drawOut\" hidden>\n        <div class=\"morph\"><div class=\"pic\" id=\"morphA\"></div><span class=\"arrow\">→</span><div class=\"pic\" id=\"morphB\"></div></div>\n      </div>\n      <div class=\"loading\" id=\"drawing\" hidden><i></i>그리는 중이에요 · 20초쯤 걸려요</div>\n      <div class=\"chips\" id=\"pickRow\" hidden>\n        <button type=\"button\" class=\"btn main\" id=\"btnKeep\" style=\"flex:1\">이 그림으로 정하기</button>\n        <button type=\"button\" class=\"btn\" id=\"btnRedo\">다시 그리기</button>\n      </div>\n      <button type=\"button\" class=\"link\" id=\"btnCancelMake\" hidden>그냥 원래 그림 쓸래요</button>\n    </div>\n\n    <div class=\"card\" id=\"home\" hidden>\n      <div class=\"petName\"><h2 id=\"homeName\"></h2><span class=\"note\" id=\"homeKind\"></span></div>\n      <div class=\"room\" id=\"room\"><div class=\"bubble\" id=\"bubble\"></div></div>\n      <p class=\"brag\" id=\"brag\" hidden></p>\n      <p class=\"note\">탭하면 반응해요. 갓챠에서 방 아이템을 뽑으면 여기 생겨요</p>\n      <button type=\"button\" class=\"link\" id=\"btnRemake\">사진으로 다시 그리기</button>\n    </div>\n  </section>\n\n  <!-- 갓챠 -->\n  <section class=\"view\" id=\"vGacha\" aria-label=\"갓챠\" hidden>\n    <div class=\"card\">\n      <div class=\"roundBar\"><span class=\"left\">남은 캡슐 <b id=\"left\">-</b></span><span class=\"clock\" id=\"clock\"></span></div>\n      <div class=\"machine\" id=\"machine\"></div>\n      <p class=\"note\" style=\"text-align:center\">통 안엔 친구들 펫 굿즈랑 방 아이템이 섞여 있어요</p>\n    </div>\n    <div class=\"card\">\n      <h2>지금 줄</h2>\n      <div class=\"lineWrap\"><div class=\"line\" id=\"line\"></div></div>\n      <p class=\"myLine\" id=\"myLine\"></p>\n      <button type=\"button\" class=\"btn main big\" id=\"btnLine\" disabled>줄 서기</button>\n      <p class=\"err\" id=\"lineErr\" hidden></p>\n    </div>\n    <div class=\"card\">\n      <h2>이번 주 많이 뽑힌 펫</h2>\n      <ol class=\"rank\" id=\"rank\"></ol>\n    </div>\n  </section>\n\n  <!-- 진열장 -->\n  <section class=\"view\" id=\"vShelf\" aria-label=\"진열장\" hidden>\n    <div class=\"card\">\n      <h2>우리 방 아이템</h2>\n      <div class=\"items\" id=\"items\"></div>\n    </div>\n    <div class=\"card\">\n      <h2>모은 펫 굿즈</h2>\n      <div class=\"grid\" id=\"goods\"></div>\n    </div>\n  </section>\n</main>\n\n<nav class=\"tabs\" role=\"tablist\" aria-label=\"화면\">\n  <button role=\"tab\" data-tab=\"vPet\" aria-selected=\"true\"><svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"><ellipse cx=\"16\" cy=\"19\" rx=\"11\" ry=\"9\"/><circle cx=\"8\" cy=\"9\" r=\"3.5\"/><circle cx=\"24\" cy=\"9\" r=\"3.5\"/><circle cx=\"12\" cy=\"18\" r=\"1.2\" fill=\"currentColor\"/><circle cx=\"20\" cy=\"18\" r=\"1.2\" fill=\"currentColor\"/></svg>우리 아이</button>\n  <button role=\"tab\" data-tab=\"vGacha\" aria-selected=\"false\"><svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"><circle cx=\"16\" cy=\"12\" r=\"9\"/><path d=\"M9 20h14l-2 9H11z\"/><circle cx=\"16\" cy=\"25\" r=\"1.6\" fill=\"currentColor\"/></svg>갓챠<span class=\"dot\" id=\"gDot\" hidden></span></button>\n  <button role=\"tab\" data-tab=\"vShelf\" aria-selected=\"false\"><svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"><rect x=\"4\" y=\"5\" width=\"24\" height=\"23\" rx=\"3\"/><path d=\"M4 16h24\"/><circle cx=\"11\" cy=\"11\" r=\"2.5\"/><rect x=\"18\" y=\"20\" width=\"5\" height=\"5\" rx=\"1\"/></svg>진열장</button>\n</nav>\n\n<div class=\"gate\" id=\"gate\" hidden>\n  <div class=\"card\">\n    <img src=\"/style.jpg\" alt=\"꼬리별 햄찌\">\n    <h1>꼬리<span>별</span></h1>\n    <p class=\"note\">우리 애를 꼬리별 친구로 만들고, 친구들이랑 같은 갓챠 줄에 서요</p>\n    <label class=\"f\">입장 코드<input type=\"text\" id=\"gCode\" autocomplete=\"off\" placeholder=\"친구가 알려준 코드\"></label>\n    <label class=\"f\">내 닉네임<input type=\"text\" id=\"gNick\" maxlength=\"12\" autocomplete=\"off\" placeholder=\"예: 메롱\"></label>\n    <p class=\"err\" id=\"gErr\" hidden></p>\n    <button type=\"button\" class=\"btn main big\" id=\"gGo\">들어가기</button>\n  </div>\n</div>\n\n<div class=\"modal\" id=\"modal\" hidden>\n  <div class=\"card\" id=\"modalCard\"></div>\n</div>\n<div class=\"toast\" id=\"toast\" hidden></div>\n\n<script>\nconst $ = s => document.querySelector(s);\nconst esc = s => String(s ?? '').replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst store = {\n  get(k) { try { return localStorage.getItem('kk_' + k); } catch (e) { return null; } },\n  set(k, v) { try { localStorage.setItem('kk_' + k, v); } catch (e) {} },\n};\nconst S = { code: store.get('code') || '', nick: store.get('nick') || '', id: store.get('id') || '', state: null, offset: 0, tab: 'vPet', lastSt: '', drawsLeft: null };\nif (!S.id) { S.id = (crypto.randomUUID ? crypto.randomUUID() : String(Math.random()).slice(2) + Date.now()).replace(/[^a-f0-9]/gi, '').toLowerCase().slice(0, 24); store.set('id', S.id); }\nconst now = () => Date.now() + S.offset;\n\nasync function api(path, body) {\n  const r = await fetch('/api/' + path, { method: body ? 'POST' : 'GET', headers: { 'content-type': 'application/json', 'x-code': S.code }, body: body ? JSON.stringify(body) : undefined });\n  const j = await r.json().catch(() => ({}));\n  if (!r.ok) { const e = new Error(j.message || '잠시 뒤 다시 해 주세요'); e.code = j.error; e.status = r.status; throw e; }\n  return j;\n}\nfunction toast(t) { const el = $('#toast'); el.textContent = t; el.hidden = false; clearTimeout(toast.t); toast.t = setTimeout(() => el.hidden = true, 2600); }\n\n/* ---------- 그림 조각 ---------- */\nconst KIND = { hamster: '햄찌', dog: '강아지', cat: '고양이' };\nconst GOODS = { sticker: '스티커', keyring: '키링', plush: '말랑 인형', figure: '잠자는 피규어' };\nconst ITEMS = { slide: '미끄럼틀', hammock: '해먹', lamp: '달 조명', cloud: '구름 침대' };\nconst ITEM_ORDER = ['hammock', 'slide', 'lamp', 'cloud'];\nconst INK = '#4A3428';\n/* 손님 햄스터·아직 그림 없는 펫은 코드로 그린 찹쌀떡 */\nfunction critter(kind, fur) {\n  const f = fur || '#F3D9B1';\n  const ears = kind === 'cat'\n    ? `<path d=\"M-24 -10 L-20 -32 L-6 -20Z M24 -10 L20 -32 L6 -20Z\" fill=\"${f}\" stroke=\"${INK}\" stroke-width=\"3\" stroke-linejoin=\"round\"/>`\n    : kind === 'dog'\n    ? `<ellipse cx=\"-25\" cy=\"-2\" rx=\"9\" ry=\"15\" fill=\"${f}\" stroke=\"${INK}\" stroke-width=\"3\" transform=\"rotate(18 -25 -2)\"/><ellipse cx=\"25\" cy=\"-2\" rx=\"9\" ry=\"15\" fill=\"${f}\" stroke=\"${INK}\" stroke-width=\"3\" transform=\"rotate(-18 25 -2)\"/>`\n    : `<circle cx=\"-17\" cy=\"-20\" r=\"8\" fill=\"${f}\" stroke=\"${INK}\" stroke-width=\"3\"/><circle cx=\"17\" cy=\"-20\" r=\"8\" fill=\"${f}\" stroke=\"${INK}\" stroke-width=\"3\"/><circle cx=\"-17\" cy=\"-20\" r=\"3.5\" fill=\"#F2A7B8\"/><circle cx=\"17\" cy=\"-20\" r=\"3.5\" fill=\"#F2A7B8\"/>`;\n  return `<svg viewBox=\"-40 -40 80 80\" aria-hidden=\"true\"><rect x=\"-40\" y=\"-40\" width=\"80\" height=\"80\" fill=\"#FFF8EE\"/>${kind === 'dog' ? '' : ears}<ellipse cx=\"0\" cy=\"6\" rx=\"30\" ry=\"26\" fill=\"${f}\" stroke=\"${INK}\" stroke-width=\"3\"/>${kind === 'dog' ? ears : ''}<circle cx=\"-10\" cy=\"2\" r=\"3.6\" fill=\"${INK}\"/><circle cx=\"10\" cy=\"2\" r=\"3.6\" fill=\"${INK}\"/><circle cx=\"-9\" cy=\"0.8\" r=\"1.2\" fill=\"#fff\"/><circle cx=\"11\" cy=\"0.8\" r=\"1.2\" fill=\"#fff\"/><ellipse cx=\"-18\" cy=\"10\" rx=\"5\" ry=\"3\" fill=\"#F5A9B8\"/><ellipse cx=\"18\" cy=\"10\" rx=\"5\" ry=\"3\" fill=\"#F5A9B8\"/><path d=\"M-4 9 q4 4 4 0 q0 4 4 0\" stroke=\"${INK}\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\"/></svg>`;\n}\nfunction petFace(petId, label) {\n  const p = S.state?.pets?.[petId];\n  if (p && p.img) return `<img src=\"/api/img/${encodeURIComponent(petId)}?v=${p.v}&c=${encodeURIComponent(S.code)}\" alt=\"${esc(label || p.name)}\" loading=\"lazy\">`;\n  return critter(p?.kind || 'hamster', p?.fur);\n}\nconst ITEM_SVG = {\n  slide: `<svg viewBox=\"0 0 100 90\" aria-hidden=\"true\"><path d=\"M14 86 V22 M34 86 V22\" stroke=\"${INK}\" stroke-width=\"4\"/><path d=\"M14 38h20M14 54h20M14 70h20\" stroke=\"${INK}\" stroke-width=\"3\"/><rect x=\"10\" y=\"16\" width=\"30\" height=\"8\" rx=\"3\" fill=\"#BFE3D0\" stroke=\"${INK}\" stroke-width=\"3\"/><path d=\"M36 20 C62 22 66 70 94 82 L90 88 C58 78 54 34 34 30Z\" fill=\"#F7B6C6\" stroke=\"${INK}\" stroke-width=\"3\" stroke-linejoin=\"round\"/></svg>`,\n  hammock: `<svg viewBox=\"0 0 100 80\" aria-hidden=\"true\"><path d=\"M8 78 V14 M92 78 V14\" stroke=\"${INK}\" stroke-width=\"4\" stroke-linecap=\"round\"/><path d=\"M8 24 C30 64 70 64 92 24 C70 50 30 50 8 24Z\" fill=\"#BFE3D0\" stroke=\"${INK}\" stroke-width=\"3\" stroke-linejoin=\"round\"/><path d=\"M30 42 l3 6 l6 1 l-5 4 l1 6 l-5 -3 l-5 3 l1 -6 l-5 -4 l6 -1z\" fill=\"#FFE7A6\" stroke=\"${INK}\" stroke-width=\"1.5\"/></svg>`,\n  lamp: `<svg viewBox=\"0 0 60 100\" aria-hidden=\"true\"><path d=\"M30 0 V38\" stroke=\"${INK}\" stroke-width=\"2.5\"/><circle cx=\"30\" cy=\"62\" r=\"26\" fill=\"#FFF3C4\" opacity=\".55\"/><path d=\"M38 42 A20 20 0 1 0 40 80 A16 16 0 1 1 38 42Z\" fill=\"#FFE08A\" stroke=\"${INK}\" stroke-width=\"3\" stroke-linejoin=\"round\"/></svg>`,\n  cloud: `<svg viewBox=\"0 0 100 64\" aria-hidden=\"true\"><path d=\"M18 52 C4 52 4 32 18 32 C18 16 40 12 46 24 C52 8 78 10 78 28 C94 26 98 52 80 52Z\" fill=\"#FFFFFF\" stroke=\"${INK}\" stroke-width=\"3\" stroke-linejoin=\"round\"/><path d=\"M22 46 h56 v6 h-56z\" fill=\"#F7B6C6\" stroke=\"${INK}\" stroke-width=\"2.5\"/><text x=\"70\" y=\"22\" font-family=\"Jua\" font-size=\"12\" fill=\"${INK}\">z</text><text x=\"78\" y=\"14\" font-family=\"Jua\" font-size=\"9\" fill=\"${INK}\">z</text></svg>`,\n};\nfunction goodsHTML(petId, type, count) {\n  const p = S.state?.pets?.[petId] || { name: '???' };\n  const extra = type === 'keyring' ? '<i class=\"ring\"></i>' : type === 'figure' ? '<i class=\"star\">★</i>' : '';\n  return `<div class=\"good g-${type}\">${count > 1 ? `<span class=\"cnt\">×${count}</span>` : ''}<div class=\"frame\">${extra}<div class=\"face\">${petFace(petId)}</div></div><b>${esc(p.name)}</b><span>${GOODS[type]}</span></div>`;\n}\n\n/* ---------- 입장 ---------- */\nasync function enter() {\n  const code = $('#gCode').value.trim(), nick = $('#gNick').value.trim();\n  const err = $('#gErr'); err.hidden = true;\n  if (!code || !nick) { err.textContent = '코드와 닉네임을 둘 다 적어 주세요'; err.hidden = false; return; }\n  S.code = code; S.nick = nick;\n  $('#gGo').disabled = true;\n  try {\n    const r = await api('hello', { id: S.id, nick });\n    store.set('code', code); store.set('nick', nick); S.drawsLeft = r.drawsLeft;\n    $('#gate').hidden = true; boot();\n  } catch (e) { err.textContent = e.message; err.hidden = false; }\n  $('#gGo').disabled = false;\n}\n$('#gGo').onclick = enter;\n\n/* ---------- 상태 받아오기 ---------- */\nasync function refresh() {\n  try {\n    const t0 = Date.now(), st = await api('state?id=' + S.id);\n    S.offset = st.now - (t0 + Date.now()) / 2; S.state = st;\n    render();\n  } catch (e) {\n    if (e.status === 401) { store.set('code', ''); $('#gate').hidden = false; }\n  }\n}\nfunction render() {\n  const st = S.state; if (!st) return;\n  $('#who').textContent = S.nick ? `${S.nick}님` : '';\n  renderPet(); renderGacha(); renderShelf();\n  if (st.me.st === 'turn' && S.lastSt !== 'turn') alertTurn();\n  S.lastSt = st.me.st;\n  $('#gDot').hidden = !(st.me.st === 'turn' || (st.me.st === 'none' && st.round.joinable));\n}\n\n/* ---------- 우리 아이 ---------- */\nlet making = false, kind = 'hamster', photoData = '', drawn = '';\nfunction myPet() { return S.state?.pets?.[S.id]; }\nfunction renderPet() {\n  const p = myPet(), showMaker = making || !p || !p.img;\n  $('#maker').hidden = !showMaker; $('#home').hidden = showMaker;\n  $('#btnCancelMake').hidden = !(making && p && p.img);\n  if (S.drawsLeft != null) $('#drawLeft').textContent = `오늘 그리기 ${S.drawsLeft}번 남았어요`;\n  if (showMaker) return;\n  $('#homeName').textContent = p.name; $('#homeKind').textContent = KIND[p.kind] || '';\n  const owned = new Set((S.state.mine || []).filter(x => x.kind === 'item').map(x => x.a));\n  const key = [...owned].sort().join(',') + '|' + p.v;\n  if ($('#room').dataset.key !== key) {\n    $('#room').dataset.key = key;\n    $('#room').innerHTML = ITEM_ORDER.filter(i => owned.has(i)).map(i => `<div class=\"it ${i}\">${ITEM_SVG[i]}</div>`).join('') +\n      `<div class=\"pet\" id=\"roomPet\"><div class=\"bob\">${petFace(S.id)}</div></div><div class=\"bubble\" id=\"bubble\"></div>`;\n    $('#roomPet').onclick = poke;\n  }\n  const n = S.state.pulledMe;\n  $('#brag').hidden = !n; $('#brag').textContent = `${p.name} 굿즈가 친구 캡슐에서 ${n}번 나왔어요`;\n}\nconst LINES = { hamster: ['냠냠…', '해씨 줘!', '볼 빵빵', '쳇바퀴 가자'], dog: ['멍~', '산책 가쟈!', '헤헤', '간식?'], cat: ['냥~', '…', '쓰다듬어도 돼', '꾹꾹'] };\nfunction poke(e) {\n  const p = myPet(); if (!p) return;\n  const L = LINES[p.kind] || LINES.hamster, b = $('#bubble');\n  b.textContent = L[Math.floor(Math.random() * L.length)]; b.classList.add('on');\n  clearTimeout(poke.t); poke.t = setTimeout(() => b.classList.remove('on'), 1500);\n  const r = $('#room').getBoundingClientRect(), h = document.createElement('span');\n  h.className = 'heart'; h.textContent = '♥'; h.style.left = (e.clientX - r.left - 8) + 'px'; h.style.top = (e.clientY - r.top - 20) + 'px';\n  $('#room').appendChild(h); setTimeout(() => h.remove(), 1200);\n}\ndocument.querySelectorAll('[data-kind]').forEach(b => b.onclick = () => {\n  kind = b.dataset.kind; document.querySelectorAll('[data-kind]').forEach(x => x.setAttribute('aria-pressed', String(x === b)));\n});\nfunction loadImg(src) { return new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = src; }); }\nasync function toJpeg(src, max, q) {\n  const img = await loadImg(src), k = Math.min(1, max / Math.max(img.width, img.height));\n  const c = document.createElement('canvas'); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);\n  const g = c.getContext('2d'); g.fillStyle = '#FFF8EE'; g.fillRect(0, 0, c.width, c.height); g.drawImage(img, 0, 0, c.width, c.height);\n  return c.toDataURL('image/jpeg', q);\n}\nasync function onPhoto(e) {\n  const f = e.target.files[0]; if (!f) return;\n  const url = URL.createObjectURL(f);\n  try { photoData = await toJpeg(url, 768, .86); } catch (err) { showMakeErr('이 사진은 열 수 없어요. 다른 사진으로 해 주세요'); return; } finally { URL.revokeObjectURL(url); }\n  $('#drop').innerHTML = `<img src=\"${photoData}\" alt=\"고른 사진\"><input type=\"file\" id=\"photo\" accept=\"image/*\" aria-label=\"사진 바꾸기\">`;\n  $('#photo').onchange = onPhoto;\n  $('#makeErr').hidden = true;\n}\n$('#photo').onchange = onPhoto;\nfunction showMakeErr(t) { $('#makeErr').textContent = t; $('#makeErr').hidden = false; }\nasync function doDraw() {\n  if (!photoData) return showMakeErr('먼저 사진을 골라 주세요');\n  if (!$('#petName').value.trim()) { $('#petName').focus(); return showMakeErr('이름을 적어 주세요'); }\n  $('#makeErr').hidden = true; $('#btnDraw').disabled = true; $('#btnRedo').disabled = true;\n  $('#drawing').hidden = false; $('#pickRow').hidden = true;\n  try {\n    const r = await api('draw', { id: S.id, kind, photo: photoData.split(',')[1] });\n    drawn = `data:${r.mime};base64,${r.image}`; S.drawsLeft = r.left;\n    $('#morphA').innerHTML = `<img src=\"${photoData}\" alt=\"원래 사진\">`;\n    $('#morphB').innerHTML = `<img src=\"${drawn}\" alt=\"꼬리별 그림\">`;\n    $('#drawOut').hidden = false; $('#pickRow').hidden = false; $('#btnDraw').hidden = true;\n  } catch (e) {\n    if (e.code === 'quota') S.drawsLeft = 0;\n    showMakeErr(e.message);\n  }\n  $('#drawing').hidden = true; $('#btnDraw').disabled = false; $('#btnRedo').disabled = false; renderPet();\n}\n$('#btnDraw').onclick = doDraw; $('#btnRedo').onclick = doDraw;\n$('#btnKeep').onclick = async () => {\n  $('#btnKeep').disabled = true;\n  try {\n    const img = await toJpeg(drawn, 448, .85);\n    await api('pet', { id: S.id, name: $('#petName').value.trim(), kind, img });\n    making = false; $('#drawOut').hidden = true; $('#pickRow').hidden = true; $('#btnDraw').hidden = false;\n    await refresh(); toast('우리 아이가 꼬리별에 왔어요');\n  } catch (e) { showMakeErr(e.message); }\n  $('#btnKeep').disabled = false;\n};\n$('#btnRemake').onclick = () => { making = true; const p = myPet(); if (p) { $('#petName').value = p.name; } renderPet(); };\n$('#btnCancelMake').onclick = () => { making = false; renderPet(); };\n\n/* ---------- 갓챠 ---------- */\nfunction machineSVG(st) {\n  const ids = Object.keys(st.pets).sort((a, b) => (st.pets[b].img ? 1 : 0) - (st.pets[a].img ? 1 : 0)).slice(0, 7);\n  const spots = [[-28, -12], [4, -26], [30, -6], [-10, 12], [20, 18], [-36, 16], [42, 22]];\n  const caps = ['#F7B6C6', '#BFE3D0', '#FFE7A6', '#C9D8F6', '#F7B6C6', '#FFE7A6', '#BFE3D0'];\n  const balls = ids.map((id, i) => {\n    const [x, y] = spots[i], p = st.pets[id];\n    const inner = p.img ? `<image href=\"/api/img/${encodeURIComponent(id)}?v=${p.v}&c=${encodeURIComponent(S.code)}\" x=\"${x - 15}\" y=\"${y - 15}\" width=\"30\" height=\"30\" clip-path=\"url(#cp${i})\" preserveAspectRatio=\"xMidYMid slice\"/>` : `<svg x=\"${x - 15}\" y=\"${y - 15}\" width=\"30\" height=\"30\" viewBox=\"-40 -40 80 80\">${critter(p.kind, p.fur).replace(/^<svg[^>]*>|<\\/svg>$/g, '')}</svg>`;\n    return `<clipPath id=\"cp${i}\"><circle cx=\"${x}\" cy=\"${y}\" r=\"15\"/></clipPath><circle cx=\"${x}\" cy=\"${y}\" r=\"17\" fill=\"${caps[i]}\" stroke=\"${INK}\" stroke-width=\"2\"/>${inner}<circle cx=\"${x}\" cy=\"${y}\" r=\"15\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"1.5\"/>`;\n  }).join('');\n  return `<svg viewBox=\"-80 -80 160 200\" role=\"img\" aria-label=\"갓챠 기계\"><circle cx=\"0\" cy=\"0\" r=\"62\" fill=\"#FFFFFF\" stroke=\"${INK}\" stroke-width=\"3.5\"/><g>${balls}</g><path d=\"M-36 -40 q14 -14 30 -16\" stroke=\"#FFFFFF\" stroke-width=\"6\" stroke-linecap=\"round\" opacity=\".9\"/><path d=\"M-58 50 h116 l-10 60 h-96z\" fill=\"#F2A0B3\" stroke=\"${INK}\" stroke-width=\"3.5\" stroke-linejoin=\"round\"/><path d=\"M-62 46 h124\" stroke=\"${INK}\" stroke-width=\"7\" stroke-linecap=\"round\"/><circle cx=\"0\" cy=\"78\" r=\"15\" fill=\"#FFFFFF\" stroke=\"${INK}\" stroke-width=\"3\"/><rect x=\"-3\" y=\"66\" width=\"6\" height=\"24\" rx=\"3\" fill=\"${INK}\"/><rect x=\"-22\" y=\"96\" width=\"44\" height=\"10\" rx=\"4\" fill=\"#E07C95\" stroke=\"${INK}\" stroke-width=\"2.5\"/></svg>`;\n}\nfunction fmt(ms) { ms = Math.max(0, ms); const m = Math.floor(ms / 60000), s = Math.floor(ms / 1000) % 60; return `${m}:${String(s).padStart(2, '0')}`; }\nfunction renderGacha() {\n  const st = S.state, R = st.round;\n  $('#left').textContent = `${R.left}/${R.stock}`;\n  const mKey = Object.entries(st.pets).map(([k, v]) => k + (v.v || '')).join();\n  if ($('#machine').dataset.key !== mKey) { $('#machine').dataset.key = mKey; $('#machine').innerHTML = machineSVG(st); }\n  const line = $('#line');\n  line.innerHTML = st.line.length ? st.line.map(e => {\n    const p = st.pets[e.pet] || {}, me = e.id === S.id;\n    const nm = me ? '나' : e.npc ? p.name : (e.nick || p.name || '손님');\n    return `<div class=\"qp ${me ? 'me' : ''} ${e.st === 'turn' || (e.npc && e.t - now() < 15000) ? 'turn' : ''}\"><span class=\"no\">${e.no}번</span><div class=\"av\">${p.name ? petFace(e.pet) : critter('hamster', '#EADCCB')}</div><span class=\"nm\">${esc(nm)}</span></div>`;\n  }).join('') : `<p class=\"lineEmpty\">아직 아무도 없어요. 1번으로 서 보세요</p>`;\n  tickGacha();\n  const rank = $('#rank');\n  rank.innerHTML = st.rank.length ? st.rank.map((r, i) => {\n    const p = st.pets[r.pet] || { name: '???' };\n    return `<li class=\"${r.pet === S.id ? 'mine' : ''}\"><span class=\"medal\">${i + 1}</span><span class=\"av\">${petFace(r.pet)}</span><span class=\"nm\">${esc(p.name)}<small>${p.npc ? '꼬리별 주민' : esc(p.owner ? p.owner + '네' : '')}</small></span><span class=\"ct\">${r.n}번</span></li>`;\n  }).join('') : `<li class=\"empty\">아직 아무도 안 뽑았어요. 첫 캡슐의 주인공이 돼 보세요</li>`;\n}\nfunction tickGacha() {\n  const st = S.state; if (!st) return;\n  const R = st.round, me = st.me, t = now(), btn = $('#btnLine');\n  $('#clock').textContent = `다음 입고 ${fmt(R.re - t)}`;\n  btn.classList.remove('urgent'); btn.disabled = false;\n  let txt = '', sub = '';\n  if (me.st === 'none') {\n    if (R.joinable) { btn.textContent = '줄 서기'; txt = '캡슐이 남아 있어요'; sub = '서면 몇 번째인지 바로 알려 줘요'; }\n    else { btn.textContent = '줄 서기'; btn.disabled = true; txt = '이번 판은 마감됐어요'; sub = `${fmt(R.re - t)} 뒤에 새 캡슐이 들어와요`; }\n  } else if (me.st === 'wait') {\n    btn.textContent = '기다리는 중'; btn.disabled = true;\n    txt = me.ahead > 0 ? `내 앞에 ${me.ahead}명` : '곧 내 차례!'; sub = `약 ${fmt(me.t - t)} 뒤 · ${me.no}번째로 섰어요`;\n  } else if (me.st === 'turn') {\n    btn.textContent = '뽑기하기'; btn.classList.add('urgent'); txt = '내 차례예요!'; sub = `${fmt(me.until - t)} 안에 뽑아 주세요`;\n  } else if (me.st === 'done') {\n    btn.textContent = '이번 판 뽑기 완료'; btn.disabled = true; txt = '진열장에서 확인해 보세요'; sub = `다음 판까지 ${fmt(R.re - t)}`;\n  } else if (me.st === 'soldout') {\n    btn.textContent = '품절'; btn.disabled = true; txt = '앞에서 캡슐이 다 떨어졌어요'; sub = `다음 판까지 ${fmt(R.re - t)}`;\n  } else if (me.st === 'missed') {\n    btn.textContent = '차례를 놓쳤어요'; btn.disabled = true; txt = '다음 판엔 꼭 뽑아요'; sub = `다음 판까지 ${fmt(R.re - t)}`;\n  }\n  /* 시계가 넘어가면 서버 상태보다 먼저 버튼을 맞춰 줌 */\n  if (me.st === 'wait' && t >= me.t) { btn.textContent = '뽑기하기'; btn.disabled = false; btn.classList.add('urgent'); txt = '내 차례예요!'; sub = ''; }\n  $('#myLine').innerHTML = `${esc(txt)}${sub ? `<small>${esc(sub)}</small>` : ''}`;\n  if (t >= R.re && !tickGacha.pending) { tickGacha.pending = true; refresh().finally(() => tickGacha.pending = false); }\n}\n$('#btnLine').onclick = async () => {\n  const st = S.state; if (!st) return;\n  $('#lineErr').hidden = true; $('#btnLine').disabled = true;\n  try {\n    if (st.me.st === 'none') { await api('join', { id: S.id }); unlockAudio(); await refresh(); toast('줄 섰어요. 차례가 오면 알려 줄게요'); }\n    else { const r = await api('pull', { id: S.id }); await showResult(r.result); refresh(); }\n  } catch (e) { $('#lineErr').textContent = e.message; $('#lineErr').hidden = false; refresh(); }\n};\nfunction showResult(res) {\n  return new Promise(done => {\n    const m = $('#modal'), c = $('#modalCard');\n    c.innerHTML = `<h3 style=\"font-size:22px\">두근두근</h3><div class=\"capsule shake\" id=\"cap\"><div class=\"top\"></div><div class=\"bot\"></div></div>`;\n    m.hidden = false; $('#machine').classList.add('shake'); setTimeout(() => $('#machine').classList.remove('shake'), 1000);\n    setTimeout(() => $('#cap').classList.replace('shake', 'open'), 1000);\n    setTimeout(() => {\n      let body;\n      if (res.kind === 'item') {\n        const rare = res.a === 'cloud';\n        body = `<span class=\"badge ${rare ? 'rare' : ''}\">${rare ? '★ 레어 아이템' : '방 아이템'}</span><div class=\"reveal\">${ITEM_SVG[res.a]}</div><h3 style=\"font-size:22px\">${ITEMS[res.a]} 나왔다!</h3><p class=\"note\">우리 아이 방에 바로 놓았어요</p>`;\n      } else {\n        const p = S.state.pets[res.a] || { name: '???' }, rare = res.b === 'figure', mine = res.a === S.id;\n        body = `<span class=\"badge ${rare ? 'rare' : ''}\">${rare ? '★ 레어 굿즈' : '펫 굿즈'}</span><div class=\"reveal\">${goodsHTML(res.a, res.b, 1)}</div><h3 style=\"font-size:22px\">${esc(p.name)} ${GOODS[res.b]} 나왔다!</h3><p class=\"note\">${mine ? '우리 애가 나왔어요!' : p.npc ? '꼬리별 주민이에요' : `${esc(p.owner || '친구')}네 아이예요`}</p>`;\n      }\n      c.innerHTML = body + `<button type=\"button\" class=\"btn main big\" id=\"mOk\">진열장에 넣기</button>`;\n      $('#mOk').onclick = () => { m.hidden = true; done(); };\n    }, 1600);\n  });\n}\n\n/* ---------- 진열장 ---------- */\nfunction renderShelf() {\n  const mine = S.state.mine || [], own = {};\n  mine.filter(x => x.kind === 'item').forEach(x => own[x.a] = (own[x.a] || 0) + 1);\n  $('#items').innerHTML = ITEM_ORDER.map(i => `<div class=\"item ${i === 'cloud' ? 'rare' : ''} ${own[i] ? '' : 'locked'}\">${ITEM_SVG[i]}<b>${own[i] ? ITEMS[i] : '???'}</b>${own[i] > 1 ? `<span>×${own[i]}</span>` : ''}</div>`).join('');\n  const g = {};\n  mine.filter(x => x.kind === 'pet').forEach(x => { const k = x.a + '|' + x.b; g[k] = (g[k] || 0) + 1; });\n  const keys = Object.keys(g);\n  $('#goods').innerHTML = keys.length ? keys.map(k => { const [a, b] = k.split('|'); return goodsHTML(a, b, g[k]); }).join('') : `<p class=\"note\" style=\"grid-column:1/-1\">아직 없어요. 갓챠에서 친구들 펫 굿즈를 모아 보세요</p>`;\n}\n\n/* ---------- 내 차례 알림 ---------- */\nlet actx = null;\nfunction unlockAudio() { try { actx = actx || new (window.AudioContext || window.webkitAudioContext)(); actx.resume(); } catch (e) {} }\nfunction alertTurn() {\n  try { navigator.vibrate && navigator.vibrate([200, 100, 200]); } catch (e) {}\n  if (actx) { [880, 1175, 1568].forEach((f, i) => { const o = actx.createOscillator(), g = actx.createGain(), t = actx.currentTime + i * .14; o.frequency.value = f; g.gain.setValueAtTime(.12, t); g.gain.exponentialRampToValueAtTime(.001, t + .25); o.connect(g).connect(actx.destination); o.start(t); o.stop(t + .26); }); }\n  document.title = '내 차례! · 꼬리별';\n  toast('내 차례예요! 갓챠에서 뽑아 주세요');\n}\ndocument.addEventListener('visibilitychange', () => { if (!document.hidden) { document.title = '꼬리별'; refresh(); } });\n\n/* ---------- 탭 ---------- */\ndocument.querySelectorAll('[data-tab]').forEach(b => b.onclick = () => {\n  S.tab = b.dataset.tab;\n  document.querySelectorAll('[data-tab]').forEach(x => x.setAttribute('aria-selected', String(x === b)));\n  ['vPet', 'vGacha', 'vShelf'].forEach(v => $('#' + v).hidden = v !== S.tab);\n  window.scrollTo(0, 0); unlockAudio();\n  if (S.tab === 'vGacha') document.title = '꼬리별';\n});\n\nfunction boot() {\n  $('#who').textContent = `${S.nick}님`;\n  refresh();\n  clearInterval(boot.p); clearInterval(boot.c);\n  boot.p = setInterval(() => { if (!document.hidden) refresh(); }, 3000);\n  boot.c = setInterval(tickGacha, 1000);\n}\nif (S.code && S.nick) {\n  api('hello', { id: S.id, nick: S.nick }).then(r => { S.drawsLeft = r.drawsLeft; boot(); }).catch(() => { $('#gCode').value = ''; $('#gNick').value = S.nick; $('#gate').hidden = false; });\n} else { $('#gNick').value = S.nick; $('#gate').hidden = false; }\n</script>\n</body>\n</html>\n";
const STYLE_B64 = "";

/* ---------- 게임 규칙 (데모용 숫자) ---------- */
const ROUND_MS = 10 * 60e3;   // 10분마다 캡슐 입고
const OPEN_DELAY = 30e3;      // 판 시작 30초 뒤 첫 손님 뽑기
const SERV = 15e3;            // 한 명당 15초
const MINWAIT = 20e3;         // 줄 서면 최소 20초는 기다림
const WINDOW = 120e3;         // 내 차례 오면 2분 안에 뽑기
const JOIN_CLOSE = 60e3;      // 판 끝나기 1분 전엔 줄 마감
const DRAW_PER_PLAYER = 4;    // AI 그림: 한 사람 하루 4번
const DRAW_PER_DAY = 25;      // AI 그림: 전체 하루 25번 (요금 안전장치)

const NPC_PETS = [
  { id: "npc-kongtteok", name: "콩떡", kind: "hamster", fur: "#F3D9B1" },
  { id: "npc-hodu", name: "호두", kind: "hamster", fur: "#C08A5B" },
  { id: "npc-mochi", name: "모찌", kind: "dog", fur: "#FFF1DE" },
  { id: "npc-nyang", name: "냥냥", kind: "cat", fur: "#9A949E" },
];
const ITEMS = [
  { id: "slide", w: 30 }, { id: "hammock", w: 30 }, { id: "lamp", w: 30 }, { id: "cloud", w: 10 },
];
const GOODS = [
  { id: "sticker", w: 40 }, { id: "keyring", w: 35 }, { id: "plush", w: 18 }, { id: "figure", w: 7 },
];

const json = (o, status = 200) => new Response(JSON.stringify(o), { status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });
function rng(seed) { let s = (seed >>> 0) || 1; return () => { s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; }; }
function hash(str) { let h = 2166136261; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
function pickW(list, r) { const sum = list.reduce((a, b) => a + b.w, 0); let x = r * sum; for (const it of list) { if ((x -= it.w) <= 0) return it; } return list[list.length - 1]; }
function toB64(buf) { const u = new Uint8Array(buf); let s = ""; for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode.apply(null, u.subarray(i, i + 0x8000)); return btoa(s); }
const validId = id => typeof id === "string" && /^[a-z0-9-]{8,40}$/.test(id);
const kst = t => new Date(t + 9 * 3600e3).toISOString().slice(0, 10);

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    if (!url.pathname.startsWith("/api/")) {
      if (url.pathname === "/" || url.pathname === "/index.html") return new Response(INDEX_HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } });
      if (url.pathname === "/style.jpg") return new Response(Uint8Array.from(atob(STYLE_B64), c => c.charCodeAt(0)), { headers: { "content-type": "image/jpeg", "cache-control": "public, max-age=86400" } });
      return new Response("", { status: 404 });
    }
    if (!env.ACCESS_CODE) return json({ error: "setup", message: "ACCESS_CODE가 아직 설정되지 않았어요" }, 503);
    const code = req.headers.get("x-code") || url.searchParams.get("c");
    if (code !== env.ACCESS_CODE) return json({ error: "code", message: "입장 코드가 달라요" }, 401);
    const hub = env.HUB.get(env.HUB.idFromName("main"));
    if (url.pathname === "/api/draw" && req.method === "POST") return draw(req, env, hub);
    return hub.fetch(req);
  },
};

/* ---------- 사진 → 꼬리별 그림체 (Gemini) ---------- */
const KIND_KO = { hamster: "hamster", dog: "puppy", cat: "cat" };
async function draw(req, env, hub) {
  if (!env.GEMINI_API_KEY) return json({ error: "setup", message: "GEMINI_API_KEY가 아직 설정되지 않았어요" }, 503);
  let body; try { body = await req.json(); } catch { return json({ error: "bad", message: "요청이 이상해요" }, 400); }
  const { id, kind, photo } = body || {};
  if (!validId(id) || typeof photo !== "string" || photo.length < 1000 || photo.length > 3_000_000) return json({ error: "bad", message: "사진을 다시 골라 주세요" }, 400);
  const q = await hub.fetch(new Request(new URL("/api/quota", req.url), { method: "POST", body: JSON.stringify({ id }) })).then(r => r.json());
  if (!q.ok) return json({ error: "quota", message: q.message, left: 0 }, 429);

  const style = STYLE_B64;
  const animal = KIND_KO[kind] || "pet";
  const prompt =
    `Redraw the ${animal} in the FIRST image as a cute chibi character illustration, in exactly the art style of the SECOND image. ` +
    `Style: round mochi-like chubby body, soft dark-brown hand-drawn outline, fuzzy fur strokes along the edge, big glossy black dot eyes, pink blush cheeks, tiny pink paws, flat warm pastel colors. ` +
    `Keep this pet's real fur colors, markings, ear shape and hair length from the photo so the owner recognizes it. ` +
    `One character only, full body, centered, facing the viewer, plain cream background (#FDF6EC), no text, no frame, no extra objects.`;
  const imgs = [{ mime: "image/jpeg", data: photo }, { mime: "image/jpeg", data: style }];

  const tries = [
    () => callInteractions(env, prompt, imgs, true),
    () => callInteractions(env, prompt, imgs, false),
    () => callGenerate(env, prompt, imgs),
  ];
  let lastErr = "";
  for (const t of tries) {
    try { const out = await t(); if (out) return json({ image: out.data, mime: out.mime, left: q.left }); }
    catch (e) { lastErr = String(e.message || e).slice(0, 300); }
  }
  await hub.fetch(new Request(new URL("/api/quota", req.url), { method: "POST", body: JSON.stringify({ id, refund: true }) }));
  return json({ error: "ai", message: "그림을 못 받아왔어요. 잠시 뒤 다시 해 주세요 (횟수는 안 깎였어요)", detail: lastErr }, 502);
}
async function callInteractions(env, prompt, imgs, withFormat) {
  const body = {
    model: "gemini-nano-banana-2.1",
    input: [{ type: "text", text: prompt }, ...imgs.map(i => ({ type: "image", mime_type: i.mime, data: i.data }))],
  };
  if (withFormat) body.response_format = { type: "image", mime_type: "image/jpeg", aspect_ratio: "1:1", image_size: "1K" };
  const r = await fetch("https://generativelanguage.googleapis.com/v1beta/interactions", {
    method: "POST", headers: { "content-type": "application/json", "x-goog-api-key": env.GEMINI_API_KEY }, body: JSON.stringify(body),
  });
  if (!r.ok) throw new Error(`interactions ${r.status}: ${(await r.text()).slice(0, 200)}`);
  return findImage(await r.json());
}
async function callGenerate(env, prompt, imgs) {
  const body = { contents: [{ parts: [{ text: prompt }, ...imgs.map(i => ({ inline_data: { mime_type: i.mime, data: i.data } }))] }], generationConfig: { responseModalities: ["IMAGE"] } };
  const r = await fetch("https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-image:generateContent", {
    method: "POST", headers: { "content-type": "application/json", "x-goog-api-key": env.GEMINI_API_KEY }, body: JSON.stringify(body),
  });
  if (!r.ok) throw new Error(`generate ${r.status}: ${(await r.text()).slice(0, 200)}`);
  return findImage(await r.json());
}
/* 응답 모양이 바뀌어도 그림 데이터를 찾아냄 (마지막 그림이 결과) */
function findImage(o) {
  let found = null;
  const walk = v => {
    if (!v || typeof v !== "object") return;
    if (Array.isArray(v)) return v.forEach(walk);
    const d = v.inlineData || v.inline_data;
    if (d && typeof d.data === "string" && d.data.length > 1000) found = { data: d.data, mime: d.mimeType || d.mime_type || "image/png" };
    else if (v.type === "image" && typeof v.data === "string" && v.data.length > 1000) found = { data: v.data, mime: v.mime_type || v.mimeType || "image/png" };
    for (const k in v) walk(v[k]);
  };
  walk(o);
  return found;
}

/* ---------- 공용 저장소: 플레이어·펫·줄·뽑기 ---------- */
export class Hub extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    this.sql = ctx.storage.sql;
    this.sql.exec("CREATE TABLE IF NOT EXISTS players(id TEXT PRIMARY KEY, nick TEXT, at INTEGER)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS pets(id TEXT PRIMARY KEY, name TEXT, kind TEXT, img TEXT, at INTEGER)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS queue(r INTEGER, id TEXT, at INTEGER, PRIMARY KEY(r, id))");
    this.sql.exec("CREATE TABLE IF NOT EXISTS pulls(uniq TEXT PRIMARY KEY, who TEXT, r INTEGER, t INTEGER, kind TEXT, a TEXT, b TEXT)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS quota(day TEXT, id TEXT, n INTEGER, PRIMARY KEY(day, id))");
  }
  rows(q, ...a) { return this.sql.exec(q, ...a).toArray(); }

  async fetch(req) {
    const url = new URL(req.url), p = url.pathname, now = Date.now();
    let b = {};
    if (req.method === "POST") { try { b = await req.json(); } catch { return json({ error: "bad", message: "요청이 이상해요" }, 400); } }

    if (p.startsWith("/api/img/")) {
      const r = this.rows("SELECT img FROM pets WHERE id = ?", p.slice(9))[0];
      if (!r || !r.img) return new Response("", { status: 404 });
      const m = /^data:(image\/[a-z]+);base64,(.+)$/.exec(r.img);
      if (!m) return new Response("", { status: 404 });
      const bin = Uint8Array.from(atob(m[2]), c => c.charCodeAt(0));
      return new Response(bin, { headers: { "content-type": m[1], "cache-control": "public, max-age=86400" } });
    }
    if (p === "/api/quota") {
      const day = kst(now);
      if (b.refund) { this.sql.exec("UPDATE quota SET n = MAX(0, n - 1) WHERE day = ? AND id = ?", day, b.id); return json({ ok: true }); }
      const total = this.rows("SELECT COALESCE(SUM(n),0) AS n FROM quota WHERE day = ?", day)[0].n;
      const mine = (this.rows("SELECT n FROM quota WHERE day = ? AND id = ?", day, b.id)[0] || { n: 0 }).n;
      if (mine >= DRAW_PER_PLAYER) return json({ ok: false, message: `오늘 그리기 ${DRAW_PER_PLAYER}번을 다 썼어요. 내일 다시 해 주세요` });
      if (total >= DRAW_PER_DAY) return json({ ok: false, message: "오늘 전체 그리기 횟수가 다 찼어요. 내일 다시 해 주세요" });
      this.sql.exec("INSERT INTO quota(day, id, n) VALUES(?, ?, 1) ON CONFLICT(day, id) DO UPDATE SET n = n + 1", day, b.id);
      return json({ ok: true, left: DRAW_PER_PLAYER - mine - 1 });
    }
    if (p === "/api/hello") {
      if (!validId(b.id)) return json({ error: "bad", message: "다시 들어와 주세요" }, 400);
      const nick = String(b.nick || "").trim().slice(0, 12) || "손님";
      this.sql.exec("INSERT INTO players(id, nick, at) VALUES(?, ?, ?) ON CONFLICT(id) DO UPDATE SET nick = excluded.nick", b.id, nick, now);
      const day = kst(now), used = (this.rows("SELECT n FROM quota WHERE day = ? AND id = ?", day, b.id)[0] || { n: 0 }).n;
      return json({ ok: true, drawsLeft: Math.max(0, DRAW_PER_PLAYER - used) });
    }
    if (p === "/api/pet") {
      if (!this.player(b.id)) return json({ error: "who", message: "다시 들어와 주세요" }, 400);
      const name = String(b.name || "").trim().slice(0, 12);
      if (!name) return json({ error: "bad", message: "이름을 적어 주세요" }, 400);
      if (typeof b.img !== "string" || !/^data:image\/(jpeg|png|webp);base64,/.test(b.img) || b.img.length > 400_000) return json({ error: "bad", message: "그림이 너무 커요" }, 400);
      const kind = ["hamster", "dog", "cat"].includes(b.kind) ? b.kind : "hamster";
      this.sql.exec("INSERT INTO pets(id, name, kind, img, at) VALUES(?, ?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET name = excluded.name, kind = excluded.kind, img = excluded.img, at = excluded.at", b.id, name, kind, b.img, now);
      return json({ ok: true });
    }
    if (p === "/api/join") {
      if (!this.player(b.id)) return json({ error: "who", message: "다시 들어와 주세요" }, 400);
      const R = this.round(now);
      if (R.entries.some(e => e.id === b.id)) return json({ ok: true });
      if (!R.joinable) return json({ error: "closed", message: R.arrived >= R.stock ? "이번 판 캡슐이 이미 다 예약됐어요" : "이번 판 줄은 마감됐어요" }, 409);
      this.sql.exec("INSERT OR IGNORE INTO queue(r, id, at) VALUES(?, ?, ?)", R.r, b.id, now);
      return json({ ok: true });
    }
    if (p === "/api/pull") {
      const R = this.round(now), me = R.entries.find(e => e.id === b.id);
      if (!me) return json({ error: "noline", message: "먼저 줄을 서 주세요" }, 409);
      if (!me.gets) return json({ error: "soldout", message: "앞에서 캡슐이 다 떨어졌어요" }, 409);
      if (now < me.t) return json({ error: "wait", message: "아직 차례가 아니에요" }, 409);
      if (now > me.t + WINDOW) return json({ error: "missed", message: "차례 시간이 지나 버렸어요" }, 409);
      const uniq = `${R.r}:${b.id}`;
      const had = this.rows("SELECT kind, a, b FROM pulls WHERE uniq = ?", uniq)[0];
      if (had) return json({ ok: true, result: had });
      const out = this.roll(Math.random, b.id);
      this.sql.exec("INSERT INTO pulls(uniq, who, r, t, kind, a, b) VALUES(?, ?, ?, ?, ?, ?, ?)", uniq, b.id, R.r, now, out.kind, out.a, out.b);
      return json({ ok: true, result: out });
    }
    if (p === "/api/state") return json(this.state(url.searchParams.get("id") || "", now));
    return json({ error: "none", message: "없는 주소예요" }, 404);
  }

  player(id) { return validId(id) && this.rows("SELECT id FROM players WHERE id = ?", id)[0]; }
  pool() { return [...this.rows("SELECT id FROM pets WHERE img IS NOT NULL").map(r => r.id), ...NPC_PETS.map(n => n.id)]; }
  roll(R, who) {
    const pool = this.pool();
    if (R() < .5) return { kind: "item", a: pickW(ITEMS, R()).id, b: "" };
    return { kind: "pet", a: pool[Math.floor(R() * pool.length)], b: pickW(GOODS, R()).id };
  }

  /* 한 판의 줄: 손님 햄스터(NPC) + 진짜 친구들, 들어온 순서대로 15초씩 */
  round(now) {
    const r = Math.floor(now / ROUND_MS), rs = r * ROUND_MS, R = rng(Math.imul(r, 2654435761) ^ 0x5bd1e995);
    const stock = 4 + Math.floor(R() * 4), nNpc = 2 + Math.floor(R() * 3);
    const entries = [];
    for (let i = 0; i < nNpc; i++) { const pet = NPC_PETS[Math.floor(R() * NPC_PETS.length)]; entries.push({ id: `npc:${r}:${i}`, pet: pet.id, at: rs + Math.floor(R() * 150e3), npc: true }); }
    for (const q of this.rows("SELECT id, at FROM queue WHERE r = ?", r)) entries.push({ id: q.id, pet: q.id, at: q.at, npc: false });
    entries.sort((a, b) => a.at - b.at || (a.id < b.id ? -1 : 1));
    let prev = rs + OPEN_DELAY - SERV;
    entries.forEach((e, i) => { e.t = Math.max(prev + SERV, e.at + MINWAIT, rs + OPEN_DELAY); prev = e.t; e.gets = i < stock; });
    /* 손님 햄스터는 제 차례에 알아서 뽑아감 (랭킹이 살아있게) */
    for (const e of entries) {
      if (e.npc && e.gets && e.t <= now) {
        const out = this.roll(rng(hash(e.id)), e.pet);
        this.sql.exec("INSERT OR IGNORE INTO pulls(uniq, who, r, t, kind, a, b) VALUES(?, ?, ?, ?, ?, ?, ?)", e.id, e.pet, r, e.t, out.kind, out.a, out.b);
      }
    }
    /* 지금 줄 서면 몇 시에 차례가 오나: 이미 온 사람들 뒤 */
    const arrivedList = entries.filter(e => e.at <= now), re = rs + ROUND_MS;
    const lastT = arrivedList.length ? arrivedList[arrivedList.length - 1].t : rs + OPEN_DELAY - SERV;
    const tNew = Math.max(lastT + SERV, now + MINWAIT, rs + OPEN_DELAY);
    const joinable = arrivedList.length < stock && tNew + WINDOW <= re && now <= re - JOIN_CLOSE;
    return { r, rs, re, stock, entries, arrived: arrivedList.length, joinable };
  }

  state(id, now) {
    const R = this.round(now);
    const pulled = new Set(this.rows("SELECT uniq FROM pulls WHERE r = ?", R.r).map(x => x.uniq));
    const key = e => e.npc ? e.id : `${R.r}:${e.id}`;
    const players = Object.fromEntries(this.rows("SELECT id, nick FROM players").map(x => [x.id, x.nick]));
    const pets = {};
    for (const n of NPC_PETS) pets[n.id] = { name: n.name, kind: n.kind, fur: n.fur, npc: true };
    for (const x of this.rows("SELECT id, name, kind, at, img IS NOT NULL AS has FROM pets")) pets[x.id] = { name: x.name, kind: x.kind, v: x.at, img: !!x.has, owner: players[x.id] || "" };

    const line = [];
    R.entries.forEach((e, i) => {
      if (e.at > now) return;
      const done = pulled.has(key(e));
      const inWindow = now >= e.t && now <= e.t + WINDOW;
      let st = "wait";
      if (!e.gets) st = "soldout";
      else if (e.npc) st = e.t <= now ? "done" : "wait";
      else if (done) st = "done";
      else if (inWindow) st = "turn";
      else if (now > e.t + WINDOW) st = "missed";
      if (st === "done" || st === "missed" || (st === "soldout" && e.id !== id)) return;
      line.push({ no: i + 1, id: e.id, pet: e.pet, npc: e.npc, nick: e.npc ? "" : (players[e.id] || "손님"), st, t: e.t });
    });
    const used = R.entries.filter(e => e.gets && e.t <= now).length;
    const meE = R.entries.find(e => e.id === id);
    let me = { st: "none" };
    if (meE) {
      const i = R.entries.indexOf(meE), ahead = line.filter(x => x.no < i + 1).length;
      const done = pulled.has(key(meE));
      me = { no: i + 1, ahead, t: meE.t, until: meE.t + WINDOW, gets: meE.gets,
        st: done ? "done" : !meE.gets ? "soldout" : now < meE.t ? "wait" : now <= meE.t + WINDOW ? "turn" : "missed" };
    }
    const week = now - 7 * 864e5;
    const rank = this.rows("SELECT a AS pet, COUNT(*) AS n FROM pulls WHERE kind = 'pet' AND t > ? GROUP BY a ORDER BY n DESC LIMIT 5", week);
    const mine = id ? this.rows("SELECT kind, a, b, t FROM pulls WHERE who = ? ORDER BY t DESC LIMIT 300", id) : [];
    const pulledMe = id ? this.rows("SELECT COUNT(*) AS n FROM pulls WHERE kind = 'pet' AND a = ? AND who != ?", id, id)[0].n : 0;
    const joinable = !meE && R.joinable;
    return {
      now, round: { r: R.r, rs: R.rs, re: R.re, stock: R.stock, left: Math.max(0, R.stock - used), booked: R.arrived, joinable, window: WINDOW },
      line, me, pets, rank, mine, pulledMe,
    };
  }
}
